    # Collapse repeated columns of a horizontally encoded palette.
    palette = []
    for c, color in bands:
        if not palette or palette[-1] != color:
            palette.append(color)
    # Demo's palette is vertical, hence each palette color occupies a single
    # column with repeated cells; horizontal palettes have each color repeated
    # down a column. In either case, the ordered color list is extracted below.
    if len(palette) < 2:
        # General extraction: find a contiguous rectangular repeated-color
