    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] != 0:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            comps.append(cells)
    return comps


def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = _components(grid)
    # The template is the largest connected monochromatic color-1 object.
    shapes = [cells for cells in comps if all(grid[r][c] == 1 for r,c in cells)]
    if not shapes:
        raise ValueError('template not found')
    shape_cells = max(shapes, key=len)
    r0 = min(r for r,c in shape_cells)
    r1 = max(r for r,c in shape_cells)
    c0 = min(c for r,c in shape_cells)
    c1 = max(c for r,c in shape_cells)
    shape = [(r-r0,c-c0) for r,c in shape_cells]
    sh = r1-r0+1

    # A separate multicolor rectangular code gives the ordered colors by column.
    palettes = []
    shape_set = set(shape_cells)
    for cells in comps:
        if set(cells) == shape_set:
            continue
        colors = {grid[r][c] for r,c in cells}
        if 1 not in colors or len(colors) < 2:
            continue
        by_col = {}
        for r,c in cells:
            by_col.setdefault(c, []).append(grid[r][c])
        seq = []
        for c in sorted(by_col):
            vals = by_col[c]
            # Each palette column repeats one color vertically.
            counts = {}
            for v in vals:
                counts[v] = counts.get(v, 0) + 1
            seq.append(max(counts, key=counts.get))
        compact = []
        for v in seq:
            if not compact or compact[-1] != v:
                compact.append(v)
        if len(compact) >= 2 and 1 in compact:
            palettes.append(compact)
    if not palettes:
        raise ValueError('ordered palette not found')
    palette = max(palettes, key=len)
    i1 = palette.index(1)

    out = [[0 for _ in range(w)] for _ in range(h)]
    for i, color in enumerate(palette):
        top = r0 + (i-i1)*sh
        for dr, dc in shape:
            rr, cc = top+dr, c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
